// The integration suite exercises the flows that carry the product's security
// promises — single-use QR, approval gating, consent capture, throttling — end
// to end against a real PostgreSQL. Set VISITFLOW_TEST_DSN to a server the test
// may create and drop databases on; without it the suite skips.
const testAdminPassword = "integration-test-password"

type testEnv struct {
	server  *Server
	handler http.Handler
	cookies []*http.Cookie
	csrf    string
	t       *testing.T
}

func randomSuffix(t *testing.T) string {
	t.Helper()
	b := make([]byte, 8)
	if _, err := rand.Read(b); err != nil {
		t.Fatalf("random: %v", err)
	}
	return fmt.Sprintf("%x", b)
}

func newTestEnv(t *testing.T) *testEnv {
	t.Helper()
	adminDSN := strings.TrimSpace(os.Getenv("VISITFLOW_TEST_DSN"))
	if adminDSN == "" {
		t.Skip("VISITFLOW_TEST_DSN is not set; skipping PostgreSQL integration test")
	}
	ctx := context.Background()
	adminPool, err := pgxpool.New(ctx, adminDSN)
	if err != nil {
		t.Fatalf("connect admin database: %v", err)
	}
	if err := adminPool.Ping(ctx); err != nil {
		adminPool.Close()
		t.Fatalf("ping admin database: %v", err)
	}
	name := "visitflow_test_" + randomSuffix(t)
	if _, err := adminPool.Exec(ctx, `CREATE DATABASE `+name); err != nil {
		adminPool.Close()
		t.Fatalf("create test database: %v", err)
	}
	parsed, err := url.Parse(adminDSN)
	if err != nil {
		t.Fatalf("parse dsn: %v", err)
	}
	parsed.Path = "/" + name
	pool, err := database.Open(ctx, parsed.String())
	if err != nil {
		t.Fatalf("open test database: %v", err)
	}
	t.Cleanup(func() {
		pool.Close()
		if _, err := adminPool.Exec(context.Background(), `DROP DATABASE IF EXISTS `+name+` WITH (FORCE)`); err != nil {
			t.Logf("drop test database: %v", err)
		}
		adminPool.Close()
	})
	server := newServerForPool(t, pool)
	env := &testEnv{server: server, handler: server.Routes(), t: t}
	env.login("admin", testAdminPassword)
	return env
}

func newServerForPool(t *testing.T, pool *pgxpool.Pool) *Server {
	t.Helper()
	key := make([]byte, 32)
	if _, err := rand.Read(key); err != nil {
		t.Fatalf("random key: %v", err)
	}
	keyring, err := platform.NewKeyringFromSecret(base64.StdEncoding.EncodeToString(key))
	if err != nil {
		t.Fatalf("keyring: %v", err)
	}
	server := NewServer(pool, keyring, slog.New(slog.NewTextHandler(io.Discard, nil)),
		fstest.MapFS{"index.html": {Data: []byte("<html><head></head><body>spa</body></html>")}}, "test", "test", "test")
	ctx := context.Background()
	if err := server.EnsureEncryptionKey(ctx); err != nil {
		t.Fatalf("encryption key: %v", err)
	}
	if err := server.EnsureBootstrapAdmin(ctx, "admin", testAdminPassword); err != nil {
		t.Fatalf("bootstrap admin: %v", err)
	}
	return server
}

// testRequestTimeout bounds a single request made through do or doForwarded.
// No request in this suite takes more than a few seconds, so a request that is
// still running at this point is stuck. Failing that one test — with the path
// that stalled — beats letting the whole package run into go test's timeout,
// where the only diagnosis is a stack dump of every goroutine.
const testRequestTimeout = 30 * time.Second

// requestContext derives a request context from the test's own, so a request
// is cancelled either when it stalls or when its test has already ended.
func (e *testEnv) requestContext() (context.Context, context.CancelFunc) {
	return context.WithTimeout(e.t.Context(), testRequestTimeout)
}

// requestTimedOut reports why a request should fail its test, or "" if its
// context simply ran to completion.
func requestTimedOut(ctx context.Context, method, path string) string {
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return fmt.Sprintf("%s %s did not finish within %s; the handler is stuck", method, path, testRequestTimeout)
	}
	return ""
}

func (e *testEnv) do(method, path string, body any) *httptest.ResponseRecorder {
	e.t.Helper()
	ctx, cancel := e.requestContext()
	defer cancel()
	response := e.doWithContext(ctx, method, path, body)
	if reason := requestTimedOut(ctx, method, path); reason != "" {
		e.t.Fatal(reason)
	}
	return response
}

